import{_ as p,a0 as l,w as b,s as o,I as i,x as a,a1 as n,A as t,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"在 Ubuntu 16.04 Server 上安装 Zabbix | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 16.04 Server 上安装 Zabbix | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 16.04 Server 上安装 Zabbix | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 16.04 Server 上安装 Zabbix | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170705 Monitoring Server Install Zabbix on an Ubuntu 16.04 Server","title":"在 Ubuntu 16.04 Server 上安装 Zabbix","tag":"201708","desc":""},"relativePath":"201708/20170705 Monitoring Server Install Zabbix on an Ubuntu 16.04 Server.md","filePath":"[post].md"}'),d={name:"201708/20170705 Monitoring Server Install Zabbix on an Ubuntu 16.04 Server.md"};function h(g,s,c,u,x,k){const e=l("Link");return b(),o("div",null,[s[16]||(s[16]=i("h1",{id:"在-ubuntu-16-04-server-上安装-zabbix",tabindex:"-1"},[a("在 Ubuntu 16.04 Server 上安装 Zabbix "),i("a",{class:"header-anchor",href:"#在-ubuntu-16-04-server-上安装-zabbix","aria-label":"Permalink to “在 Ubuntu 16.04 Server 上安装 Zabbix”"},"​")],-1)),i("p",null,[n(e,{href:"https://www.unixmen.com/wp-content/uploads/2017/06/zabbix_logo.png"},{default:t(()=>[...s[0]||(s[0]=[i("img",{src:"https://www.unixmen.com/wp-content/uploads/2017/06/zabbix_logo.png",alt:"Zabbix logo",title:"zabbix_logo"},null,-1)])]),_:1})]),s[17]||(s[17]=i("h3",{id:"监控服务器-什么是-zabbix",tabindex:"-1"},[a("监控服务器 - 什么是 Zabbix "),i("a",{class:"header-anchor",href:"#监控服务器-什么是-zabbix","aria-label":"Permalink to “监控服务器 - 什么是 Zabbix”"},"​")],-1)),i("p",null,[n(e,{href:"http://www.zabbix.com/"},{default:t(()=>[...s[1]||(s[1]=[a("Zabbix",-1)])]),_:1}),s[2]||(s[2]=a(" 是企业级开源分布式监控服务器解决方案。该软件能监控网络的不同参数以及服务器的完整性，还允许为任何事件配置基于电子邮件的警报。Zabbix 根据存储在数据库（例如 MySQL）中的数据提供报告和数据可视化功能。软件收集的每个测量指标都可以通过基于 Web 的界面访问。",-1))]),s[18]||(s[18]=r(`<p>Zabbix 根据 GNU 通用公共许可证版本 2（GPLv2）的条款发布，完全免费。</p><p>在本教程中，我们将在运行 MySQL、Apache 和 PHP 的 Ubuntu 16.04 server 上安装 Zabbix。</p><h3 id="安装-zabbix-服务器" tabindex="-1">安装 Zabbix 服务器 <a class="header-anchor" href="#安装-zabbix-服务器" aria-label="Permalink to “安装 Zabbix 服务器”">​</a></h3><p>首先，我们需要安装 Zabbix 所需的几个 PHP 模块：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install php7.0-bcmath php7.0-xml php7.0-mbstring</span></span></code></pre></div><p>Ubuntu 仓库中提供的 Zabbix 软件包已经过时了。使用官方 Zabbix 仓库安装最新的稳定版本。</p><p>通过执行以下命令来安装仓库软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://repo.zabbix.com/zabbix/3.2/ubuntu/pool/main/z/zabbix-release/zabbix-release_3.2-1+xenial_all.deb</span></span>
<span class="line"><span># dpkg -i zabbix-release_3.2-1+xenial_all.deb</span></span></code></pre></div><p>然后更新 <code>apt</code> 包源：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get update</span></span></code></pre></div><p>现在可以安装带有 MySQL 支持和 PHP 前端的 Zabbix 服务器。执行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install zabbix-server-mysql zabbix-frontend-php</span></span></code></pre></div><p>安装 Zabbix 代理：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install zabbix-agent</span></span></code></pre></div><p>Zabbix 现已安装。下一步是配置数据库来存储数据。</p><h3 id="为-zabbix-配置-mysql" tabindex="-1">为 Zabbix 配置 MySQL <a class="header-anchor" href="#为-zabbix-配置-mysql" aria-label="Permalink to “为 Zabbix 配置 MySQL”">​</a></h3><p>我们需要创建一个新的 MySQL 数据库，Zabbix 将用来存储收集的数据。</p><p>启动 MySQL shell：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -uroot -p</span></span></code></pre></div><p>接下来：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mysql&gt; CREATE DATABASE zabbix CHARACTER SET utf8 COLLATE utf8_bin;</span></span>
<span class="line"><span>Query OK, 1 row affected (0.00 sec)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mysql&gt; GRANT ALL PRIVILEGES ON zabbix.* TO zabbix@localhost IDENTIFIED BY &#39;usr_strong_pwd&#39;;</span></span>
<span class="line"><span>Query OK, 0 rows affected, 1 warning (0.00 sec)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mysql&gt; EXIT;</span></span>
<span class="line"><span>Bye</span></span></code></pre></div><p>接下来，导入初始表和数据。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># zcat /usr/share/doc/zabbix-server-mysql/create.sql.gz | mysql -uzabbix -p zabbix</span></span></code></pre></div><p>输入在 MySQL shell 中创建的 <strong>zabbix</strong> 用户的密码。</p><p>接下来，我们需要编辑 Zabbix 服务器配置文件，它是 <code>/etc/zabbix/zabbis_server.conf</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /etc/zabbix/zabbix_server.conf</span></span></code></pre></div><p>搜索文件的 <code>DBPassword</code> 部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>### Option: DBPassword                           </span></span>
<span class="line"><span>#       Database password. Ignored for SQLite.   </span></span>
<span class="line"><span>#       Comment this line if no password is used.</span></span>
<span class="line"><span>#                                                </span></span>
<span class="line"><span># Mandatory: no                                  </span></span>
<span class="line"><span># Default:                                       </span></span>
<span class="line"><span># DBPassword=</span></span></code></pre></div><p>取消注释 <code>DBPassword=</code> 这行，并添加在 MySQL 中创建的密码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DBPassword=usr_strong_pwd</span></span></code></pre></div><p>接下来，查找 <code>DBHost=</code> 这行并取消注释。</p><p>保存并退出。</p><h3 id="配置-php" tabindex="-1">配置 PHP <a class="header-anchor" href="#配置-php" aria-label="Permalink to “配置 PHP”">​</a></h3><p>我们需要配置 PHP 来使用 Zabbix。在安装过程中，安装程序在 <code>/etc/zabbix</code> 中创建了一个名为 <code>apache.conf</code> 的配置文件。打开此文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /etc/zabbix/apache.conf</span></span></code></pre></div><p>此时，只需要取消注释 <code>date.timezone</code> 并设置正确的时区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>&lt;IfModule mod_php7.c&gt;</span></span>
<span class="line"><span>    php_value max_execution_time 300</span></span>
<span class="line"><span>    php_value memory_limit 128M</span></span>
<span class="line"><span>    php_value post_max_size 16M</span></span>
<span class="line"><span>    php_value upload_max_filesize 2M</span></span>
<span class="line"><span>    php_value max_input_time 300</span></span>
<span class="line"><span>    php_value always_populate_raw_post_data -1</span></span>
<span class="line"><span>    php_value date.timezone Europe/Rome</span></span>
<span class="line"><span>&lt;/IfModule&gt;</span></span></code></pre></div><p>保存并退出。</p><p>此时，重启 Apache 并启动 Zabbix Server 服务，使其能够在开机时启动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart apache2</span></span>
<span class="line"><span># systemctl start zabbix-server</span></span>
<span class="line"><span># systemctl enable zabbix-server</span></span></code></pre></div><p>用 <code>systemctl</code> 检查 Zabbix 状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl status zabbix-server</span></span></code></pre></div><p>这个命令应该输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>â zabbix-server.service - Zabbix Server</span></span>
<span class="line"><span> Loaded: loaded (/lib/systemd/system/zabbix-server.service; enabled; vendor pr</span></span>
<span class="line"><span> Active: active (running) ...</span></span></code></pre></div><p>此时，Zabbix 的服务器端已经正确安装和配置了。</p><h3 id="配置-zabbix-web-前端" tabindex="-1">配置 Zabbix Web 前端 <a class="header-anchor" href="#配置-zabbix-web-前端" aria-label="Permalink to “配置 Zabbix Web 前端”">​</a></h3><p>如介绍中所述，Zabbix 有一个基于 Web 的前端，我们将用于可视化收集的数据。但是，必须配置此接口。</p><p>使用 Web 浏览器，进入 URL <code>http://localhost/zabbix</code>。</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot1.png" alt="Zabbix monitoring server Frontend Setup"></p><p>点击  <strong>Next step</strong></p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot2.png" alt="snapshot2"></p><p>确保所有的值都是 <strong>Ok</strong>，然后再次单击 <strong>Next step</strong> 。</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot3.png" alt="Zabbix MySQL configuration"></p><p>输入 MySQL <strong>zabbix</strong> 的用户密码，然后点击 <strong>Next step</strong>。</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot4.png" alt="Zabbix server details"></p><p>单击 <strong>Next step</strong> ，安装程序将显示具有所有配置参数的页面。再次检查以确保一切正确。</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot5.png" alt="Zabbix pre-installation details"></p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot6.png" alt="Zabbix installation finished"></p><p>点击 <strong>Next step</strong> 进入最后一页。</p><p>点击完成以完成前端安装。默认用户名为 <strong>Admin</strong>，密码是 <strong>zabbix</strong>。</p><h3 id="zabbix-服务器入门" tabindex="-1">Zabbix 服务器入门 <a class="header-anchor" href="#zabbix-服务器入门" aria-label="Permalink to “Zabbix 服务器入门”">​</a></h3><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot7.png" alt="Zabbix login interface"></p><p>使用上述凭证登录后，我们将看到 Zabbix 面板：</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot8.png" alt="zabbix dashboard"></p><p>前往 <strong>Administration -&gt; Users</strong>，了解已启用帐户的概况：</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot9.png" alt="Zabbix users"></p><p>通过点击 <strong>Create user</strong> 创建一个新帐户。</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot10.png" alt="Zabbix User Creation"></p><p>点击 <strong>Groups</strong> 中的 <strong>Add</strong>，然后选择一个组：</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot11.png" alt="snapshot11"></p><p>保存新用户凭证，它将显示在 <strong>Administration -&gt; Users</strong> 面板中。</p><p><strong>请注意，在 Zabbix 中，主机的访问权限分配给用户组，而不是单个用户。</strong></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>我们结束了 Zabbix Server 安装的教程。现在，监控基础设施已准备好完成其工作并收集有关需要在 Zabbix 配置中添加的服务器的数据。</p><hr>`,75)),i("p",null,[s[4]||(s[4]=a("via: ",-1)),n(e,{href:"https://www.unixmen.com/monitoring-server-install-zabbix-ubuntu-16-04/"},{default:t(()=>[...s[3]||(s[3]=[a("https://www.unixmen.com/monitoring-server-install-zabbix-ubuntu-16-04/",-1)])]),_:1})]),i("p",null,[s[8]||(s[8]=a("作者：",-1)),n(e,{href:"https://www.unixmen.com/author/tutan/"},{default:t(()=>[...s[5]||(s[5]=[a("Giuseppe Molica",-1)])]),_:1}),s[9]||(s[9]=a(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[6]||(s[6]=[a("geekpi",-1)])]),_:1}),s[10]||(s[10]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[13]||(s[13]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[12]||(s[12]=[a("Linux中国",-1)])]),_:1}),s[15]||(s[15]=a(" 荣誉推出",-1))])])}const v=p(d,[["render",h]]);export{w as __pageData,v as default};
